import os
from netrc import netrc
from pathlib import Path

def test_netrc_return_value(content, label):
    netrc_path = Path("/tmp/netrc_test")
    netrc_path.write_text(content)
    try:
        res = netrc(netrc_path).authenticators("example.com")
        print(f"{label} -> {res}")
    except Exception as e:
        print(f"{label} -> Exception: {e}")
    finally:
        if netrc_path.exists():
            netrc_path.unlink()

if __name__ == "__main__":
    test_netrc_return_value("machine example.com\n", "machine only no colon")
PY
